document.addEventListener('DOMContentLoaded',function(){var swiper=new Swiper('.swiper-container',{slidesPerView:'auto',spaceBetween:10,grabCursor:true,navigation:{nextEl:'.swiper-button-next',prevEl:'.swiper-button-prev',},pagination:{el:'.swiper-pagination',clickable:true,},});});document.addEventListener('DOMContentLoaded',function(){document.addEventListener('click',function(e){if(e.target.classList.contains('Comment-onPost')){e.preventDefault();const post_id=e.target.getAttribute('data-id');const targetDiv=document.querySelector(`.PostComments-forPosts[data-id="${post_id}"]`);if(targetDiv){targetDiv.style.display=targetDiv.style.display==='block'?'none':'block';}}});});document.addEventListener('DOMContentLoaded',function(){document.addEventListener('click',function(e){if(e.target.classList.contains('Comment-Close')){e.preventDefault();const post_id=e.target.getAttribute('data-id');const targetDiv=document.querySelector(`.PostComments-forPosts[data-id="${post_id}"]`);if(targetDiv){targetDiv.style.display=targetDiv.style.display==='block'?'none':'block';}}});});function redirectToPath(path){window.location.href=path;}
function switchTab(mode){const imageTab=document.getElementById('image-post-view');const confessionTab=document.getElementById('confession-post-view');const imageLabel=document.getElementById('imageLabel');const progressContainer=document.getElementById('confessionProgress');const emptyImageState=document.getElementById('emptyImageState');const imageInput=document.getElementById('imageInput');const imagePreviewContainer=document.getElementById('imagePreviewContainer');const buttons=document.querySelectorAll('.toggle-btn');buttons.forEach(btn=>{if(btn.getAttribute('data-mode')===mode){btn.classList.add('active');}else{btn.classList.remove('active');}});if(mode==='image'){if(imageTab)imageTab.style.display='block';if(confessionTab)confessionTab.style.display='none';if(imageLabel)imageLabel.style.display='flex';if(progressContainer)progressContainer.style.display='none';if(imageInput&&!imageInput.files.length){if(emptyImageState)emptyImageState.style.display='flex';if(imagePreviewContainer)imagePreviewContainer.style.display='none';}else if(imageInput&&imageInput.files.length){if(emptyImageState)emptyImageState.style.display='none';if(imagePreviewContainer)imagePreviewContainer.style.display='block';}}else{if(imageTab)imageTab.style.display='none';if(confessionTab)confessionTab.style.display='block';if(imageLabel)imageLabel.style.display='none';if(progressContainer)progressContainer.style.display='flex';if(emptyImageState)emptyImageState.style.display='none';}}
document.addEventListener('DOMContentLoaded',function(){const openButtons=document.querySelectorAll('.open');const postDiv=document.querySelector('.PostContainers');const closeButton=postDiv.querySelector('.close');openButtons.forEach(function(openButton){openButton.addEventListener('click',function(){postDiv.style.display='flex';const activeTab=document.querySelector('.toggle-btn.active');if(activeTab){switchTab(activeTab.getAttribute('data-mode'));}});});closeButton.addEventListener('click',function(){if(confirm('Are you sure you want to discard the post?')){postDiv.style.display='none';}});const imageInput=document.getElementById('imageInput');const imagePreviewContainer=document.getElementById('imagePreviewContainer');const imagePreview=document.getElementById('imagePreview');const removeImageBtn=document.getElementById('removeImageBtn');const emptyImageState=document.getElementById('emptyImageState');if(imageInput&&imagePreviewContainer&&imagePreview){imageInput.addEventListener('change',function(e){const file=e.target.files[0];if(file){const reader=new FileReader();reader.onload=function(event){imagePreview.src=event.target.result;imagePreviewContainer.style.display='block';imagePreviewContainer.classList.add('has-image');if(emptyImageState)emptyImageState.style.display='none';};reader.readAsDataURL(file);}});}
if(removeImageBtn&&imageInput&&imagePreviewContainer&&imagePreview){removeImageBtn.addEventListener('click',function(){imageInput.value='';imagePreview.src='';imagePreviewContainer.style.display='none';imagePreviewContainer.classList.remove('has-image');if(emptyImageState)emptyImageState.style.display='flex';});}
const userInput=document.getElementById('userInputConfession');const progressCircle=document.querySelector('.progress-container .progress');const progressText=document.querySelector('.progress-container .text');const postButton=document.querySelector('.postButton');if(userInput&&progressCircle&&progressText){userInput.addEventListener('input',function(){const text=userInput.value;const charCount=text.length;const maxChars=2200;const progress=Math.min((charCount/maxChars)*100,100);const dashOffset=94.2-(94.2*progress/100);progressCircle.style.strokeDashoffset=dashOffset;progressText.textContent=charCount+'/'+maxChars;if(charCount>=maxChars){progressCircle.style.stroke='#ff4444';}else if(charCount>=maxChars*0.8){progressCircle.style.stroke='#ffaa00';}else{progressCircle.style.stroke='#2b68ff';}
if(charCount>maxChars){postButton.disabled=true;}else{postButton.disabled=false;}});}});;